import {ATTRS,SKILLS,CLASSES,CLASS_OPTIONS,totalLevel,proficiency,unlockedFeatures,spellSlots,pactSlots,primarySpellAttr,attacksPerAction,resourceBlueprints,classLevel,martialArtsDie,sneakDice,rageData,inspirationDie,casterLevel} from './class-data.js';
import {SUBCLASS_COUNT,subclassOptions,getSubclass,subclassInitiativeBonus,subclassSkillBonus,subclassCriticalThreshold} from './subclass-data.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const clone=o=>structuredClone(o);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const uid=()=>crypto.randomUUID();
const mod=n=>Math.floor((Number(n)-10)/2);
const signed=n=>Number(n)>=0?`+${Number(n)}`:`${Number(n)}`;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const ICON_ALIAS={jets:'Interface/d20',vitalite:'Interface/potion',brassards:'Interface/bouclier',poing:'Interface/epee',social:'Interface/groupe',journal:'Interface/parchemin',inventaire:'Inventaire/divers',ki:'Interface/etoile',settings:'Interface/rouage',close:'Interface/fermer'};
const icon=name=>{const path=ICON_ALIAS[name]||name;const flat=`icone-${String(path).toLowerCase().replaceAll("/","-")}.png`;return `<img class="icon" src="./${esc(flat)}" alt="">`};
const btn=(html,cmd,cls='',disabled=false)=>`<button ${cmd?`data-cmd="${esc(cmd)}"`:''} class="${esc(cls)}" ${disabled?'disabled':''}>${html}</button>`;
const field=(label,id,value,type='text',attrs='')=>`<label>${esc(label)}<input id="${esc(id)}" type="${esc(type)}" value="${esc(value)}" ${attrs}></label>`;
const selectField=(label,id,opts,value)=>`<label>${esc(label)}<select id="${esc(id)}">${opts.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
const check=(label,id,value)=>`<label class="check"><input id="${esc(id)}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;
const heading=(title,sub,extra='')=>`<div class="page-heading"><div><h2>${esc(title)}</h2><p class="muted">${esc(sub)}</p></div>${extra}</div>`;
const card=(name,sub,ic,cmd,extra='',featured=false)=>`<div class="action-card ${featured?'featured':''}"><button class="action-main" data-cmd="${esc(cmd)}">${icon(ic)}<span class="text"><strong>${esc(name)}</strong><small>${esc(sub)}</small></span>${extra?`<em>${esc(extra)}</em>`:''}</button></div>`;
const SPELL_SCHOOLS=[['','— École —'],['abjuration','Abjuration'],['conjuration','Conjuration'],['divination','Divination'],['enchantement','Enchantement'],['evocation','Évocation'],['illusion','Illusion'],['necromancie','Nécromancie'],['transmutation','Transmutation']];
const ITEM_ICONS=[['Inventaire/divers','Divers'],['Inventaire/arme_courante_corps_a_corps','Arme courante · corps à corps'],['Inventaire/arme_courante_a_distance','Arme courante · distance'],['Inventaire/arme_de_guerre_corps_a_corps','Arme de guerre · corps à corps'],['Inventaire/arme_de_guerre_a_distance','Arme de guerre · distance'],['Inventaire/arme_a_feu','Arme à feu'],['Inventaire/munitions','Munitions'],['Inventaire/armure_legere','Armure légère'],['Inventaire/armure_intermediaire','Armure intermédiaire'],['Inventaire/armure_lourde','Armure lourde'],['Inventaire/bouclier','Bouclier'],['Inventaire/anneau','Anneau'],['Inventaire/baguette_magique','Baguette magique'],['Inventaire/baton_magique','Bâton magique'],['Inventaire/sceptre_magique','Sceptre magique'],['Inventaire/objet_merveilleux','Objet merveilleux'],['Inventaire/potion','Potion'],['Inventaire/parchemin','Parchemin'],['Inventaire/consommable','Consommable']];
const spellIcon=s=>s.school?`Ecoles_de_magie/${s.school}`:'Interface/magie';

const KEY='dnd5e-compagnon-universel-v1:'+location.pathname.replace(/index\.html$/,'');
const defaultSkills=()=>Object.fromEntries(SKILLS.map(([id])=>[id,{proficiency:0,adjustment:0}]));
const defaultSaves=()=>Object.fromEntries(Object.keys(ATTRS).map(k=>[k,{proficient:['str','con'].includes(k),adjustment:0}]));
function fresh(){return {
 schema:1,character:{name:'Nouveau héros',subtitle:'Compagnon D&D 5e',classes:[{id:'fighter',level:1,subclass:''},{id:'',level:0,subclass:''}],stats:{str:10,dex:10,con:10,int:10,wis:10,cha:10},maxHp:10,speed:9,ac:{mode:'normal',armorBase:10,maxDex:99,shieldBonus:0,adjustment:0,manual:10},initiativeAdjustment:0,saves:defaultSaves(),skills:defaultSkills(),tools:[],languages:'Commun',spellcasting:{ability:'auto',attackAdjustment:0,dcAdjustment:0}},
 hp:10,tempHp:0,conditions:[],turn:{number:1,phase:'waiting',action:false,bonus:false,reaction:false,attacksLeft:0},
 attacks:[{id:uid(),name:'Arme principale',attr:'str',proficient:true,dice:'1d8',damageAbility:true,bonusAdjustment:0,damageAdjustment:0,type:'tranchant',actionType:'action',range:'1,5 m',description:''}],
 spells:[],slotUsed:Array(9).fill(0),pactUsed:0,classResourceCurrent:{},customResources:[],customFeatures:[],
 items:[],coins:{pc:0,pa:0,pe:0,po:0,pp:0},notes:[],categories:[{id:'general',name:'Général',color:'#dfbd78'}],settings:{contrast:false,reduceMotion:false},updatedAt:new Date().toISOString()
}}
function normalize(s){const base=fresh();if(!s||s.schema!==1)return base;for(const k of Object.keys(base))if(s[k]===undefined)s[k]=clone(base[k]);for(const k of Object.keys(base.character))if(s.character[k]===undefined)s.character[k]=clone(base.character[k]);for(const k of Object.keys(ATTRS)){if(!s.character.saves[k])s.character.saves[k]={proficient:false,adjustment:0};if(!s.character.skills) s.character.skills=defaultSkills();}
 for(const [id] of SKILLS)if(!s.character.skills[id])s.character.skills[id]={proficiency:0,adjustment:0};
 s.character.classes=(s.character.classes||[]).slice(0,2).map(x=>({...x,subclass:x.subclass||''}));while(s.character.classes.length<2)s.character.classes.push({id:'',level:0,subclass:''});
 s.spells=(s.spells||[]).map(x=>({...x,school:x.school||''}));s.items=(s.items||[]).map(x=>({...x,icon:x.icon&&x.icon.includes('/')?x.icon:'Inventaire/divers'}));s.slotUsed=[...Array(9)].map((_,i)=>Math.max(0,Number(s.slotUsed?.[i]||0)));s.classResourceCurrent=s.classResourceCurrent||{};s.customResources=s.customResources||[];s.customFeatures=s.customFeatures||[];return s}
let state;try{state=normalize(JSON.parse(localStorage.getItem(KEY)))}catch{state=fresh()}
function persist(){state.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state))}
function mutate(fn){fn(state);syncResources();persist();render()}
function syncResources(){const blue=resourceBlueprints(state.character);const ids=new Set(blue.map(r=>r.id));for(const r of blue){if(state.classResourceCurrent[r.id]===undefined)state.classResourceCurrent[r.id]=r.max;state.classResourceCurrent[r.id]=clamp(Number(state.classResourceCurrent[r.id]),0,r.max)}for(const k of Object.keys(state.classResourceCurrent))if(!ids.has(k))delete state.classResourceCurrent[k];state.hp=clamp(Number(state.hp),0,Number(state.character.maxHp)||1);state.tempHp=Math.max(0,Number(state.tempHp)||0);const slots=spellSlots(state.character);state.slotUsed=state.slotUsed.map((u,i)=>clamp(u,0,slots[i]||0));state.pactUsed=clamp(state.pactUsed,0,pactSlots(state.character).slots)}
syncResources();

let view='home', combatTab='attacks', socialTab='skills', invQuery='', noteQuery='', noteCategory='', trash=false;
const sheet=$('#sheet'), body=$('#sheet-body'), toastEl=$('#toast');
function show(title,html,kicker='COMPAGNON D&D 5E'){ $('#sheet-title').textContent=title;$('#sheet-kicker').textContent=kicker;body.innerHTML=html;if(!sheet.open)sheet.showModal();document.body.classList.add('modal-open') }
function close(){if(sheet.open)sheet.close();document.body.classList.remove('modal-open')}
$('#close-sheet').onclick=close;
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastEl._t);toastEl._t=setTimeout(()=>toastEl.classList.remove('show'),3000)}

const jackBonus=()=>classLevel(state.character,'bard')>=2?Math.floor(proficiency(state.character)/2):0;
function saveProficient(k){return state.character.saves[k].proficient||classLevel(state.character,'monk')>=14||(k==='wis'&&classLevel(state.character,'rogue')>=15)}
function d(){const c=state.character,pb=proficiency(c),dex=mod(c.stats.dex);let ac;
 switch(c.ac.mode){case'barbarian':ac=10+dex+mod(c.stats.con)+Number(c.ac.shieldBonus||0);break;case'monk':ac=10+dex+mod(c.stats.wis);break;case'manual':ac=Number(c.ac.manual||10);break;default:ac=Number(c.ac.armorBase||10)+Math.min(dex,Number(c.ac.maxDex??99))+Number(c.ac.shieldBonus||0)}ac+=Number(c.ac.adjustment||0);
 const spellAttr=c.spellcasting.ability==='auto'?primarySpellAttr(c):c.spellcasting.ability;const spellMod=mod(c.stats[spellAttr]||10);return {level:totalLevel(c),pb,ac,initiative:dex+Number(c.initiativeAdjustment||0)+jackBonus()+subclassInitiativeBonus(c,mod),spellAttr,spellAttack:pb+spellMod+Number(c.spellcasting.attackAdjustment||0),spellDC:8+pb+spellMod+Number(c.spellcasting.dcAdjustment||0),passive:10+skillBonus('perception')};}
function saveBonus(k){const x=state.character.saves[k];const aura=classLevel(state.character,'paladin')>=6&&state.hp>0?mod(state.character.stats.cha):0;return mod(state.character.stats[k])+Number(x.adjustment||0)+(saveProficient(k)?proficiency(state.character):0)+aura}
function skillBonus(id){const [,,attr]=SKILLS.find(x=>x[0]===id);const x=state.character.skills[id];const trained=Number(x.proficiency||0);return mod(state.character.stats[attr])+Number(x.adjustment||0)+proficiency(state.character)*trained+(trained?0:jackBonus())+subclassSkillBonus(state.character,id,mod)}
function checkBonus(k){return mod(state.character.stats[k])+jackBonus()}
function classLine(){return state.character.classes.filter(c=>c.id&&c.level>0).map(c=>{const sub=getSubclass(c.id,c.subclass);return `${CLASSES[c.id]?.name||c.id} ${c.level}${sub?` · ${sub.name}`:''}`}).join(' / ')||'Classe à configurer'}
function activeResourceSummary(){const b=resourceBlueprints(state.character);if(!b.length)return {value:state.customResources.length,label:'RESSOURCES'};const first=b[0];return {value:`${state.classResourceCurrent[first.id]}/${first.max}`,label:first.name.toUpperCase().slice(0,12)}}

function render(){syncResources();const dv=d();document.body.dataset.view=view;document.body.classList.toggle('contrast',state.settings.contrast);document.body.classList.toggle('reduce-motion',state.settings.reduceMotion);const rs=activeResourceSummary();
 $('#header').innerHTML=`<div class="topline"><div class="brand">${icon('jets')}<div><b>${esc(state.character.name)}</b><small style="display:block">${esc(view==='home'?classLine():`${classLine()} · niveau total ${dv.level}`)}</small></div></div><div class="row"><span class="offline">Sauvegarde locale</span>${btn(icon('settings'),'settings','icon-button')}</div></div>${view!=='home'?`<div class="status">${btn(`${icon('vitalite')} <b>${state.hp}<small style="display:inline"> / ${state.character.maxHp}</small></b><small>POINTS DE VIE</small><div class="hp-meter"><i style="width:${state.hp/state.character.maxHp*100}%"></i></div>`,'health')}${btn(`<b>${state.tempHp}</b><small>PV TEMP.</small>`,'health')}${btn(`${icon('brassards')} <b>${dv.ac}</b><small>ARMURE</small>`,'character')}${btn(`<b>${rs.value}</b><small>${esc(rs.label)}</small>`,'resources')}</div>`:''}`;
 $('#main').innerHTML=view==='home'?home():view==='combat'?combat():view==='social'?social():journal();
 $('#dock').innerHTML=[['home','Accueil','jets'],['combat','Combat','poing'],['social','Social','social'],['journal','Journal','journal']].map(([id,n,ic])=>btn(`${icon(ic)}<span>${n}</span>`,`nav|${id}`,view===id?'active':'')).join('');
 bindDynamic();}
function home(){return `<section class="home"><div class="home-heading"><span class="eyebrow">COMPAGNON DE PERSONNAGE · D&D 5E</span><h1>${esc(state.character.name.toUpperCase())}</h1><p>${esc(state.character.subtitle)}</p></div><div class="home-space"></div><div class="home-menu">${[['combat','Combat','Attaques, sorts, aptitudes et ressources','poing'],['social','Social','Compétences, caractéristiques et inventaire','social'],['journal','Journal','Notes et suivi de campagne','journal']].map(([id,n,s,ic])=>`<button class="portal" data-cmd="nav|${id}">${icon(ic)}<span><strong>${n}</strong><small>${s}</small></span><span class="arrow">›</span></button>`).join('')}</div><p class="home-footer">${esc(classLine())} · ${state.hp}/${state.character.maxHp} PV · maîtrise ${signed(proficiency(state.character))}<br>Tout le personnage reste modifiable dans les réglages.</p></section>`}
function combat(){const dv=d(),t=state.turn,slots=spellSlots(state.character),pact=pactSlots(state.character);return `${heading('Combat',t.phase==='active'?'Votre tour est actif.':'Prêt pour le prochain tour.',`<span class="turn-no">${t.number}</span>`)}<div class="combat-layout"><section><div class="panel"><div class="panel-head"><span class="eyebrow">VOTRE TOUR</span>${btn(`États${state.conditions.length?' · '+state.conditions.length:''}`,'conditions','pill')}</div><div class="economy">${[['action','Action'],['bonus','Bonus'],['reaction','Réaction']].map(([k,n])=>`<div class="econ ${t[k]?'spent':''}"><b>${n}</b><small>${t[k]?'utilisée':'disponible'}</small></div>`).join('')}</div><div class="pills">${btn(`${state.character.speed} m vitesse`,'character','pill')}${btn(`Initiative ${signed(dv.initiative)}`,'roll|initiative','pill')}${btn(`Maîtrise ${signed(dv.pb)}`,'character','pill')}</div></div>
 ${state.hp===0?`<div class="panel"><h3 class="danger-text">0 PV</h3><p>Utilisez Soins/PV pour remettre le personnage en jeu ou gérez les jets de mort avec votre MJ.</p>${btn('Gérer les PV','health','primary')}</div>`:''}
 <div class="panel"><div class="row end"><div><span class="eyebrow">RESSOURCES</span><h3>${resourceBlueprints(state.character).length+state.customResources.length} compteurs</h3></div>${btn('Gérer','resources','pill')}</div>${resourcePills()}</div>
 <div class="bottom-actions">${btn('Repos','rest','quiet')}${btn(t.phase==='active'?'Terminer mon tour':'Commencer mon tour',t.phase==='active'?'end-turn':'start-turn','primary')}</div><div class="toolbar">${btn('Annuler le tour','cancel-turn','quiet',t.phase!=='active')}${btn('Réinitialiser rencontre','reset-encounter','quiet')}</div>
 ${slots.some(Boolean)||pact.slots?`<div class="panel"><span class="eyebrow">MAGIE</span><div class="pills">${slots.map((m,i)=>m?`<span class="pill">N${i+1} ${m-state.slotUsed[i]}/${m}</span>`:'').join('')}${pact.slots?`<span class="pill">Pacte N${pact.level} ${pact.slots-state.pactUsed}/${pact.slots}</span>`:''}</div></div>`:''}</section><section>
 <div class="tabs">${[['attacks','Attaques'],['features','Aptitudes'],['spells','Sorts'],['saves','Jets']].map(([id,n])=>btn(n,`combat-tab|${id}`,combatTab===id?'selected':'')).join('')}</div>${combatTab==='attacks'?attackList():combatTab==='features'?featureList():combatTab==='spells'?spellList():saveList()}</section></div>`}
function resourcePills(){const blue=resourceBlueprints(state.character);return `<div class="pills">${blue.map(r=>`<span class="pill">${esc(r.name)} ${state.classResourceCurrent[r.id]}/${r.max}</span>`).join('')}${state.customResources.map(r=>`<span class="pill">${esc(r.name)} ${r.current}/${r.max}</span>`).join('')}${!blue.length&&!state.customResources.length?'<span class="muted">Aucune ressource configurée.</span>':''}</div>`}
function attackBonus(a){return mod(state.character.stats[a.attr])+Number(a.bonusAdjustment||0)+(a.proficient?proficiency(state.character):0)}
function attackDamageMod(a){return (a.damageAbility?mod(state.character.stats[a.attr]):0)+Number(a.damageAdjustment||0)}
function attackList(){return `<div class="row end"><p class="muted" style="font-size:12px">Toucher pour lancer attaque + dégâts.</p>${btn('+ Attaque','edit-attack|new','pill')}</div>${state.attacks.map(a=>card(a.name,`${a.dice} ${signed(attackDamageMod(a))} ${a.type} · ${a.range||''}`,'poing',`attack|${a.id}`,signed(attackBonus(a)))).join('')||'<div class="empty">Aucune attaque.</div>'}<p class="section-label">Action Attaquer</p><div class="callout">${attacksPerAction(state.character)} attaque(s) avec l’action Attaquer selon les classes et niveaux actuellement configurés.</div>`}
function featureDynamic(f){const l=f.currentLevel;if(f.classId==='monk'&&f.name==='Arts martiaux')return `${f.summary} · dé martial d${martialArtsDie(l)}`;if(f.classId==='rogue'&&f.name==='Attaque sournoise')return `${f.summary} · ${sneakDice(l)}d6`;if(f.classId==='barbarian'&&f.name==='Rage'){const r=rageData(l);return `${f.summary} · +${r.bonus} dégâts · ${r.uses===99?'illimitées':r.uses+' utilisations'}`}if(f.classId==='bard'&&f.name==='Inspiration bardique')return `${f.summary} · d${inspirationDie(l)}`;return f.summary}
function allFeatures(){return [...unlockedFeatures(state.character),...state.customFeatures.map(x=>({...x,className:'Personnalisé',classId:'custom',level:x.level||1,currentLevel:99,featured:false,action:x.action||'Selon aptitude'}))]}
function featureList(){const fs=allFeatures();return `<div class="row end"><p class="muted" style="font-size:12px">Les aptitudes de classe et de sous-classe apparaissent automatiquement selon vos niveaux.</p>${btn('+ Aptitude','edit-feature|new','pill')}</div>${fs.map((f,i)=>card(f.name,`${f.className} N${f.level}${f.source?` · ${f.source}`:''} · ${featureDynamic(f)}`,f.kind==='subclass'?'Interface/etoile':f.classId==='custom'?'Interface/crayon':'Interface/eclair',`feature|${encodeURIComponent(f.classId)}|${encodeURIComponent(f.name)}|${i}`,'',f.featured)).join('')||'<div class="empty">Choisissez une classe pour afficher ses aptitudes.</div>'}`}
function spellList(){const dv=d(),slots=spellSlots(state.character),pact=pactSlots(state.character);return `<div class="panel"><div class="row end"><div><span class="eyebrow">INCANTATION</span><h3>Attaque ${signed(dv.spellAttack)} · DD ${dv.spellDC}</h3></div>${btn('Emplacements','slots','pill')}</div><small>Caractéristique : ${ATTRS[dv.spellAttr]} · niveau lanceur multiclassé ${casterLevel(state.character)}${pact.slots?` · pacte N${pact.level}`:''}</small></div><div class="row end"><p class="muted" style="font-size:12px">Chaque sort peut remplacer les calculs globaux.</p>${btn('+ Sort','edit-spell|new','pill')}</div>${state.spells.sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name,'fr')).map(s=>{const calc=spellCalc(s);return card(s.name,`N${s.level} · ${s.mode==='attack'?`attaque ${signed(calc.attack)}`:s.mode==='save'?`DD ${calc.dc} ${ATTRS[s.saveAttr]||''}`:'utilitaire'}${s.damageDice?` · ${s.damageDice} ${signed(calc.damageMod)}`:''}`,spellIcon(s),`spell|${s.id}`,'')}).join('')||'<div class="empty">Aucun sort configuré.</div>'}`}
function spellCalc(s){const dv=d(),attr=s.ability==='auto'?dv.spellAttr:s.ability,am=mod(state.character.stats[attr]);return {attr,attack:proficiency(state.character)+am+Number(state.character.spellcasting.attackAdjustment||0)+Number(s.attackAdjustment||0),dc:8+proficiency(state.character)+am+Number(state.character.spellcasting.dcAdjustment||0)+Number(s.dcAdjustment||0),damageMod:s.damageMod==='ability'?am:s.damageMod==='custom'?Number(s.customDamage||0):0}}
function saveList(){const dv=d();return `${card('Initiative','Dextérité + ajustement','jets','roll|initiative',signed(dv.initiative))}<p class="section-label">Jets de sauvegarde</p><div class="skills">${Object.entries(ATTRS).map(([k,n])=>btn(`<span>${n}<small>${saveProficient(k)?'MAÎTRISÉ':'NON MAÎTRISÉ'}</small></span><b>${signed(saveBonus(k))}</b>`,`roll|save|${k}`,'skill '+(saveProficient(k)?'trained':''))).join('')}</div><p class="section-label">Dés libres</p>${btn('Lancer des dés','free-dice','quiet')}`}
function social(){const dv=d();return heading('Social & exploration','Compétences, caractéristiques et équipement.')+`<div class="tabs">${btn('Compétences','social-tab|skills',socialTab==='skills'?'selected':'')}${btn('Inventaire','social-tab|inventory',socialTab==='inventory'?'selected':'')}</div>${socialTab==='skills'?`<div class="row end"><span class="pill">Perception passive ${dv.passive}</span>${btn('Configurer','skills-editor','pill')}</div><div class="skills" style="margin-top:12px">${SKILLS.map(([id,n,attr])=>{const x=state.character.skills[id];return btn(`<span>${n}<small>${ATTRS[attr]}${x.proficiency===2?' · EXPERTISE':x.proficiency===1?' · MAÎTRISE':''}</small></span><b>${signed(skillBonus(id))}</b>`,`roll|skill|${id}`,'skill '+(x.proficiency?'trained':''))}).join('')}</div><p class="section-label">Caractéristiques</p><div class="skills">${Object.entries(ATTRS).map(([k,n])=>btn(`<span>${n}<small>SCORE ${state.character.stats[k]}</small></span><b>${signed(checkBonus(k))}</b>`,`roll|check|${k}`,'skill')).join('')}</div><div class="panel"><h3>Outils & langues</h3><p>${state.character.tools.length?state.character.tools.map(esc).join(' · '):'Aucun outil configuré'}</p><p class="muted">${esc(state.character.languages)}</p></div>`:inventory()}`}
function inventory(){const items=state.items.filter(i=>(i.name+' '+i.description).toLowerCase().includes(invQuery.toLowerCase()));return `<div class="panel"><div class="row end"><div><span class="eyebrow">INVENTAIRE</span><h3>${state.items.length} objet(s)</h3></div>${btn(`Bourse · ${state.coins.po} po`,'coins','pill')}</div></div><input id="inventory-search" class="search" placeholder="Rechercher un objet…" value="${esc(invQuery)}"><div class="toolbar">${btn('Ajouter un objet','edit-item|new','primary')}${btn('Bourse','coins')}</div><div class="inventory" id="inventory-grid">${items.map(i=>`<button class="item-tile ${i.magic?'magical':''} ${i.equipped?'equipped':''}" data-cmd="item|${i.id}"><span class="qty">×${i.quantity}</span>${icon(i.icon||'Inventaire/divers')}<b>${esc(i.name)}</b><small>${esc(i.type||'Objet')}${i.equipped?' · équipé':''}</small></button>`).join('')||'<p>Aucun objet.</p>'}</div>`}
function journal(){const notes=state.notes.filter(n=>!!n.deleted===trash&&(!noteCategory||n.category===noteCategory)&&(n.title+' '+n.body+' '+n.tags).toLowerCase().includes(noteQuery.toLowerCase())).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return `${heading('Journal','Notes de campagne entièrement modifiables.',btn('+ Note','edit-note|new','primary'))}<input id="note-search" class="search" placeholder="Rechercher…" value="${esc(noteQuery)}"><select id="category-filter"><option value="">Toutes les catégories</option>${state.categories.map(c=>`<option value="${c.id}" ${noteCategory===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="toolbar">${btn(trash?'Notes actives':'Corbeille','trash')}${btn('Exporter JSON','export')}</div><div class="notes-list">${notes.map(n=>`<button class="note-card" style="--note-color:${state.categories.find(c=>c.id===n.category)?.color||'#dfbd78'}" data-cmd="edit-note|${n.id}"><small>${esc(state.categories.find(c=>c.id===n.category)?.name||'Sans catégorie')}</small><h3>${esc(n.title||'Sans titre')}</h3><p>${esc(n.body)}</p><small>${esc(n.tags||'')}</small></button>`).join('')||'<div class="empty"><h3>Une nouvelle page</h3><p>Ajoutez votre première note.</p></div>'}</div>`}
function bindDynamic(){const iq=$('#inventory-search');if(iq)iq.oninput=e=>{invQuery=e.target.value;render()};const nq=$('#note-search');if(nq)nq.oninput=e=>{noteQuery=e.target.value;render()};const cf=$('#category-filter');if(cf)cf.onchange=e=>{noteCategory=e.target.value;render()}}

function rollDie(sides){return 1+Math.floor(Math.random()*sides)}
function parseDice(expr,crit=false){expr=String(expr||'').replace(/\s+/g,'');if(!expr)return {rolls:[],total:0,label:'0'};const tokens=expr.match(/[+-]?(?:\d*d\d+|\d+)/gi);if(!tokens||tokens.join('')!==expr)return {rolls:[],total:0,label:'Expression invalide'};let total=0;const rolls=[],labels=[];for(const token of tokens){const sign=token.startsWith('-')?-1:1,raw=token.replace(/^[+-]/,'');if(/d/i.test(raw)){let [n,sides]=raw.toLowerCase().split('d').map(Number);n=n||1;if(crit)n*=2;const rs=Array.from({length:n},()=>rollDie(sides));total+=sign*rs.reduce((a,b)=>a+b,0);rolls.push(...rs.map(x=>sign*x));labels.push(`${sign<0?'-':labels.length?'+':''}${n}d${sides}`)}else{const v=sign*Number(raw);total+=v;labels.push(`${v>=0&&labels.length?'+':''}${v}`)}}return {rolls,total,label:labels.join('')}}
function d20Roll(bonus=0,mode='normal',minNatural=1){const a=rollDie(20),b=mode==='normal'?null:rollDie(20),raw=b===null?a:mode==='adv'?Math.max(a,b):Math.min(a,b),natural=Math.max(minNatural,raw);return {a,b,raw,natural,total:natural+bonus,raised:natural!==raw}}
function rollModal(title,bonus,opts={}){const defaultMode=opts.defaultMode||'normal',minNatural=opts.minNatural||1;show(title,`${selectField('Mode','roll-mode',[['normal','Normal'],['adv','Avantage'],['dis','Désavantage']],defaultMode)}${field('Ajustement supplémentaire','roll-extra',0,'number')}<button class="primary" id="do-roll">Lancer le d20</button><div id="roll-output"></div>`,'JET');$('#do-roll').onclick=()=>{const r=d20Roll(bonus+Number($('#roll-extra').value||0),$('#roll-mode').value,minNatural);$('#roll-output').innerHTML=`<div class="roll-result"><div class="dice"><span class="die">${r.a}</span>${r.b!==null?`<span class="die">${r.b}</span>`:''}</div><div class="total">${r.total}</div><p>${r.raised?`Talent fiable : ${r.raw} → ${r.natural}`:r.natural===20?'20 naturel':r.natural===1?'1 naturel':`d20 ${r.natural}`} · bonus ${signed(bonus+Number($('#roll-extra').value||0))}</p></div>`}}
function attackRoll(id){const a=state.attacks.find(x=>x.id===id);if(!a)return;const bonus=attackBonus(a),dmgMod=attackDamageMod(a);show(a.name,`${selectField('Mode d’attaque','attack-mode',[['normal','Normal'],['adv','Avantage'],['dis','Désavantage']],'normal')}${check('Appliquer un critique','attack-crit',false)}<button id="attack-roll" class="primary">Lancer attaque + dégâts</button><div id="attack-output"></div><hr class="divider">${btn('Modifier cette attaque',`edit-attack|${a.id}`,'quiet')}`,'ATTAQUE');$('#attack-roll').onclick=()=>{const r=d20Roll(bonus,$('#attack-mode').value),crit=$('#attack-crit').checked||r.natural>=subclassCriticalThreshold(state.character),damage=parseDice(a.dice,crit),total=damage.total+dmgMod;$('#attack-output').innerHTML=`<div class="roll-result"><div class="dice"><span class="die">${r.a}</span>${r.b!==null?`<span class="die">${r.b}</span>`:''}</div><div class="total">${r.total}</div><p>${crit?'CRITIQUE · ':''}${a.dice} ${signed(dmgMod)} ${esc(a.type)} = <b>${total}</b> dégâts</p><small>Dés de dégâts : ${damage.rolls.join(', ')||'—'}</small></div>`;if(state.turn.phase==='active'&&a.actionType==='action')mutate(s=>{if(!s.turn.action){s.turn.action=true;s.turn.attacksLeft=Math.max(0,attacksPerAction(s.character)-1)}else s.turn.attacksLeft=Math.max(0,s.turn.attacksLeft-1)})}}
function spellRoll(id){const s=state.spells.find(x=>x.id===id);if(!s)return;const c=spellCalc(s);const slots=spellSlots(state.character),pact=pactSlots(state.character),normalAvail=s.level>0?(slots[s.level-1]||0)-state.slotUsed[s.level-1]:0,pactAvail=s.level>0&&s.level<=pact.level?pact.slots-state.pactUsed:0;show(s.name,`<div class="muted-box">${s.mode==='attack'?`Attaque ${signed(c.attack)}`:s.mode==='save'?`DD ${c.dc} · sauvegarde ${ATTRS[s.saveAttr]}`:'Aucun jet automatique'}${s.damageDice?`<br>Dégâts : ${s.damageDice} ${signed(c.damageMod)} ${esc(s.damageType||'')}`:''}</div>${selectField('Mode d’attaque','spell-mode',[['normal','Normal'],['adv','Avantage'],['dis','Désavantage']],'normal')}${s.level>0?selectField('Emplacement','spell-slot',[['normal',`Normal N${s.level} · ${normalAvail} restant(s)`],['pact',`Pacte · ${pactAvail} restant(s)`],['none','Ne pas dépenser']],normalAvail>0?'normal':pactAvail>0?'pact':'none'):''}${check('Critique (double les dés de dégâts)','spell-crit',false)}<button id="cast-spell" class="primary">Résoudre le sort</button><div id="spell-output"></div><hr class="divider">${btn('Modifier ce sort',`edit-spell|${s.id}`,'quiet')}`,'SORT');$('#cast-spell').onclick=()=>{let attack=null;if(s.mode==='attack')attack=d20Roll(c.attack,$('#spell-mode').value);const crit=$('#spell-crit').checked||attack?.natural===20,damage=parseDice(s.damageDice,crit),total=damage.total+c.damageMod,successTotal=s.mode==='save'?(s.saveEffect==='none'?0:s.saveEffect==='half'?Math.floor(total/2):total):null;$('#spell-output').innerHTML=`<div class="roll-result">${attack?`<div class="dice"><span class="die">${attack.a}</span>${attack.b!==null?`<span class="die">${attack.b}</span>`:''}</div><div class="total">${attack.total}</div>`:`<div class="total">${s.mode==='save'?c.dc:'—'}</div>`}${s.damageDice?`<p>${crit?'CRITIQUE · ':''}${damage.label} ${signed(c.damageMod)} = <b>${total}</b> ${esc(s.damageType||'dégâts')}${successTotal!==null?`<br>Si sauvegarde réussie : <b>${successTotal}</b>`:''}</p>`:''}</div>`;const src=$('#spell-slot')?.value;if(s.level>0&&src==='normal'&&normalAvail>0){state.slotUsed[s.level-1]++;persist()}if(s.level>0&&src==='pact'&&pactAvail>0){state.pactUsed++;persist()}}}

function health(){show('Points de vie',`<div class="muted-box">PV ${state.hp}/${state.character.maxHp} · temporaires ${state.tempHp}</div><div class="grid2">${field('Valeur','hp-value',0,'number','min="0"')}${selectField('Opération','hp-op',[['damage','Dégâts'],['heal','Soins'],['temp','PV temporaires']], 'damage')}</div><button id="apply-hp" class="primary">Appliquer</button>`);$('#apply-hp').onclick=()=>{const n=Math.max(0,Number($('#hp-value').value||0)),op=$('#hp-op').value;mutate(s=>{if(op==='damage'){const soak=Math.min(s.tempHp,n);s.tempHp-=soak;s.hp=Math.max(0,s.hp-(n-soak))}else if(op==='heal')s.hp=Math.min(s.character.maxHp,s.hp+n);else s.tempHp=Math.max(s.tempHp,n)});close();toast('PV mis à jour.')}}
function resources(){const blue=resourceBlueprints(state.character);show('Ressources',`${blue.map(r=>`<div class="panel"><div class="row end"><div><b>${esc(r.name)}</b><small style="display:block">${esc(r.recharge)}${r.note?' · '+esc(r.note):''}</small></div><b>${state.classResourceCurrent[r.id]} / ${r.max}</b></div><div class="toolbar">${btn('− 1',`resource-dec|class|${r.id}`)}${btn('+ 1',`resource-inc|class|${r.id}`)}</div></div>`).join('')}${state.customResources.map(r=>`<div class="panel"><div class="row end"><div><b>${esc(r.name)}</b><small style="display:block">${esc(r.recharge||'Recharge personnalisée')}</small></div><b>${r.current} / ${r.max}</b></div><div class="toolbar">${btn('− 1',`resource-dec|custom|${r.id}`)}${btn('+ 1',`resource-inc|custom|${r.id}`)}${btn('Modifier',`edit-resource|${r.id}`,'quiet')}</div></div>`).join('')}${btn('+ Ressource personnalisée','edit-resource|new','primary')}`)}
function slotsEditor(){const slots=spellSlots(state.character),p=pactSlots(state.character);show('Emplacements de sorts',`${slots.map((m,i)=>m?`<div class="panel"><div class="row end"><b>Niveau ${i+1}</b><span>${m-state.slotUsed[i]} / ${m}</span></div><input data-slot="${i}" type="range" min="0" max="${m}" value="${state.slotUsed[i]}"><small>Emplacements dépensés : <span id="slot-label-${i}">${state.slotUsed[i]}</span></small></div>`:'').join('')}${p.slots?`<div class="panel"><div class="row end"><b>Pacte niveau ${p.level}</b><span>${p.slots-state.pactUsed} / ${p.slots}</span></div><input id="pact-used" type="range" min="0" max="${p.slots}" value="${state.pactUsed}"></div>`:''}<button id="save-slots" class="primary">Enregistrer</button>`);$('#save-slots').onclick=()=>{mutate(s=>{$$('[data-slot]').forEach(el=>s.slotUsed[Number(el.dataset.slot)]=Number(el.value));if($('#pact-used'))s.pactUsed=Number($('#pact-used').value)});close()}}
function rest(){show('Repos',`<div class="grid2">${btn('Repos court','do-rest|short','primary')}${btn('Repos long','do-rest|long','primary')}</div><div class="callout">Repos court : recharge les ressources indiquées « repos court/long » et les emplacements de pacte. Repos long : restaure les PV, les emplacements et toutes les ressources calculées.</div>`)}

function settings(){show('Configuration',`<p class="eyebrow">COMPAGNON UNIVERSEL · V3 · LEGACY 2014–2023</p><div class="grid2">${btn(`${icon('Interface/casque')} Fiche & classes`,'character','primary')}${btn(`${icon('Interface/d20')} Compétences`,'skills-editor')}${btn(`${icon('Interface/etoile')} Ressources perso`,'resources')}${btn(`${icon('Interface/crayon')} Aptitudes perso`,'custom-features')}${btn(`${icon('Interface/sauvegarde')} Exporter JSON`,'export')}${btn(`${icon('Interface/actualiser')} Importer JSON`,'import')}</div><div class="callout">${SUBCLASS_COUNT} sous-classes officielles Legacy 2014–2023 sont intégrées. Le choix d’une sous-classe ajoute automatiquement ses aptitudes aux paliers correspondants.</div>${check('Lisibilité renforcée','setting-contrast',state.settings.contrast)}${check('Réduire les animations','setting-motion',state.settings.reduceMotion)}<hr class="divider">${btn('Réinitialiser le personnage','hard-reset','danger')}`);$('#setting-contrast').onchange=e=>mutate(s=>s.settings.contrast=e.target.checked);$('#setting-motion').onchange=e=>mutate(s=>s.settings.reduceMotion=e.target.checked)}
function characterEditor(){const c=state.character;const classBlock=i=>{const entry=c.classes[i],subs=[['',entry.id?'— Choisir une sous-classe —':'— Sélectionnez d’abord une classe —'],...subclassOptions(entry.id)];return `<div class="class-config"><div class="grid2">${selectField(i===0?'Classe principale':'Seconde classe',`class-${i}`,[['',i===0?'—':'Aucune'],...CLASS_OPTIONS],entry.id)}${field('Niveau',`class-level-${i}`,entry.level,'number','min="0" max="20"')}</div>${selectField('Sous-classe',`subclass-${i}`,subs,entry.subclass||'')}<small class="source" id="subclass-source-${i}">${entry.subclass?esc(getSubclass(entry.id,entry.subclass)?.source||''):''}</small></div>`};show('Fiche & classes',`${field('Nom','char-name',c.name)}${field('Sous-titre','char-subtitle',c.subtitle)}<p class="section-label">Classes & sous-classes · 2 maximum</p>${classBlock(0)}${classBlock(1)}<div class="callout">Corpus utilisé : Legacy 2014–2023, cohérent avec le moteur 5e 2014 de cette application. ${SUBCLASS_COUNT} sous-classes officielles sont proposées ; leurs aptitudes se débloquent automatiquement selon le niveau de chaque classe.</div><p class="section-label">Caractéristiques</p><div class="grid2">${Object.entries(ATTRS).map(([k,n])=>field(n,`stat-${k}`,c.stats[k],'number','min="1" max="30"')).join('')}</div><p class="section-label">Combat</p><div class="grid2">${field('PV maximum','char-maxHp',c.maxHp,'number','min="1"')}${field('Vitesse (m)','char-speed',c.speed,'number','step="0.5"')}${field('Ajustement initiative','char-init',c.initiativeAdjustment,'number')}${selectField('Formule de CA','ac-mode',[['normal','Armure : base + DEX'],['barbarian','Barbare : 10 + DEX + CON'],['monk','Moine : 10 + DEX + SAG'],['manual','CA manuelle']],c.ac.mode)}${field('Base armure','ac-base',c.ac.armorBase,'number')}${field('DEX max ajouté','ac-maxdex',c.ac.maxDex,'number')}${field('Bonus bouclier','ac-shield',c.ac.shieldBonus,'number')}${field('Ajustement CA','ac-adjust',c.ac.adjustment,'number')}${field('CA manuelle','ac-manual',c.ac.manual,'number')}</div><p class="section-label">Incantation</p><div class="grid2">${selectField('Caractéristique','spell-ability',[['auto','Automatique selon classe/sous-classe'],...Object.entries(ATTRS)],c.spellcasting.ability)}${field('Ajustement attaque de sort','spell-attack-adj',c.spellcasting.attackAdjustment,'number')}${field('Ajustement DD','spell-dc-adj',c.spellcasting.dcAdjustment,'number')}</div><p class="section-label">Jets de sauvegarde</p><div class="grid2">${Object.entries(ATTRS).map(([k,n])=>check(n,`save-${k}`,c.saves[k].proficient)).join('')}</div>${field('Langues','char-languages',c.languages)}${field('Outils (séparés par des virgules)','char-tools',c.tools.join(', '))}<button id="save-character" class="primary">Enregistrer et recalculer</button>`);const refreshSubclass=i=>{const cid=$(`#class-${i}`).value,sel=$(`#subclass-${i}`),opts=[['',cid?'— Choisir une sous-classe —':'— Sélectionnez d’abord une classe —'],...subclassOptions(cid)];sel.innerHTML=opts.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('');$('#subclass-source-'+i).textContent=''};[0,1].forEach(i=>{$(`#class-${i}`).onchange=e=>{refreshSubclass(i);if(i===0){const cls=CLASSES[e.target.value];if(cls)for(const k of Object.keys(ATTRS))$(`#save-${k}`).checked=cls.saves.includes(k)}};$(`#subclass-${i}`).onchange=e=>{$(`#subclass-source-${i}`).textContent=getSubclass($(`#class-${i}`).value,e.target.value)?.source||''}});$('#save-character').onclick=()=>{const next=clone(c);next.name=$('#char-name').value.trim()||'Nouveau héros';next.subtitle=$('#char-subtitle').value;next.classes=[0,1].map(i=>({id:$(`#class-${i}`).value,level:Number($(`#class-level-${i}`).value||0),subclass:$(`#subclass-${i}`).value||''}));const total=next.classes.reduce((a,x)=>a+x.level,0);if(total<1||total>20)return toast('Le niveau total doit être compris entre 1 et 20.');if(next.classes[0].id&&next.classes[1].id&&next.classes[0].id===next.classes[1].id)return toast('Choisissez deux classes différentes.');for(const e of next.classes){if(e.subclass&&!getSubclass(e.id,e.subclass))e.subclass=''}for(const k of Object.keys(ATTRS))next.stats[k]=clamp(Number($(`#stat-${k}`).value||10),1,30);next.maxHp=Math.max(1,Number($('#char-maxHp').value||1));next.speed=Math.max(0,Number($('#char-speed').value||0));next.initiativeAdjustment=Number($('#char-init').value||0);next.ac.mode=$('#ac-mode').value;next.ac.armorBase=Number($('#ac-base').value||10);next.ac.maxDex=Number($('#ac-maxdex').value||99);next.ac.shieldBonus=Number($('#ac-shield').value||0);next.ac.adjustment=Number($('#ac-adjust').value||0);next.ac.manual=Number($('#ac-manual').value||10);next.spellcasting.ability=$('#spell-ability').value;next.spellcasting.attackAdjustment=Number($('#spell-attack-adj').value||0);next.spellcasting.dcAdjustment=Number($('#spell-dc-adj').value||0);for(const k of Object.keys(ATTRS))next.saves[k].proficient=$(`#save-${k}`).checked;next.languages=$('#char-languages').value;next.tools=$('#char-tools').value.split(',').map(x=>x.trim()).filter(Boolean);mutate(s=>s.character=next);close();toast('Fiche, classes et sous-classes recalculées.')}}
function skillsEditor(){show('Compétences',`<div class="skills">${SKILLS.map(([id,n,attr])=>{const x=state.character.skills[id];return `<label class="skill"><span>${esc(n)}<small>${ATTRS[attr]}</small></span><select id="skill-${id}"><option value="0" ${x.proficiency===0?'selected':''}>—</option><option value="1" ${x.proficiency===1?'selected':''}>Maîtrise</option><option value="2" ${x.proficiency===2?'selected':''}>Expertise</option></select></label>`}).join('')}</div><button id="save-skills" class="primary">Enregistrer</button>`);$('#save-skills').onclick=()=>{mutate(s=>{for(const [id] of SKILLS)s.character.skills[id].proficiency=Number($(`#skill-${id}`).value)});close()}}
function attackEditor(id){const a=id==='new'?{id:uid(),name:'Nouvelle attaque',attr:'str',proficient:true,dice:'1d8',damageAbility:true,bonusAdjustment:0,damageAdjustment:0,type:'tranchant',actionType:'action',range:'1,5 m',description:''}:state.attacks.find(x=>x.id===id);if(!a)return;show(id==='new'?'Nouvelle attaque':a.name,`${field('Nom','atk-name',a.name)}<div class="grid2">${selectField('Caractéristique','atk-attr',Object.entries(ATTRS),a.attr)}${field('Dés de dégâts','atk-dice',a.dice)}${field('Type de dégâts','atk-type',a.type)}${field('Portée','atk-range',a.range)}${selectField('Économie','atk-action',[['action','Action'],['bonus','Action bonus'],['reaction','Réaction'],['free','Libre']],a.actionType)}${field('Ajustement attaque','atk-bonus',a.bonusAdjustment,'number')}${field('Ajustement dégâts','atk-dmg',a.damageAdjustment,'number')}</div>${check('Ajouter la maîtrise au toucher','atk-prof',a.proficient)}${check('Ajouter la caractéristique aux dégâts','atk-ability-dmg',a.damageAbility)}<label>Description<textarea id="atk-desc">${esc(a.description||'')}</textarea></label><div class="sheet-actions">${id==='new'?'':btn('Supprimer',`delete-attack|${a.id}`,'danger')}<button id="save-attack" class="primary">Enregistrer</button></div>`);$('#save-attack').onclick=()=>{const n={...a,name:$('#atk-name').value.trim()||'Attaque',attr:$('#atk-attr').value,dice:$('#atk-dice').value.trim()||'1d4',type:$('#atk-type').value,range:$('#atk-range').value,actionType:$('#atk-action').value,bonusAdjustment:Number($('#atk-bonus').value||0),damageAdjustment:Number($('#atk-dmg').value||0),proficient:$('#atk-prof').checked,damageAbility:$('#atk-ability-dmg').checked,description:$('#atk-desc').value};mutate(s=>{const i=s.attacks.findIndex(x=>x.id===n.id);if(i<0)s.attacks.push(n);else s.attacks[i]=n});close()}}
function spellEditor(id){const s=id==='new'?{id:uid(),name:'Nouveau sort',level:1,school:'',mode:'attack',ability:'auto',saveAttr:'dex',saveEffect:'half',damageDice:'1d8',damageMod:'none',customDamage:0,damageType:'',attackAdjustment:0,dcAdjustment:0,description:''}:state.spells.find(x=>x.id===id);if(!s)return;show(id==='new'?'Nouveau sort':s.name,`${field('Nom','spl-name',s.name)}<div class="grid2">${field('Niveau','spl-level',s.level,'number','min="0" max="9"')}${selectField('École','spl-school',SPELL_SCHOOLS,s.school||'')}${selectField('Type de résolution','spl-mode',[['attack','Attaque de sort'],['save','Sauvegarde'],['utility','Utilitaire']],s.mode)}${selectField('Caractéristique','spl-ability',[['auto','Automatique'],...Object.entries(ATTRS)],s.ability)}${selectField('Sauvegarde visée','spl-save',Object.entries(ATTRS),s.saveAttr)}${selectField('Sur sauvegarde réussie','spl-saveeffect',[['half','Moitié des dégâts'],['none','Aucun dégât'],['full','Dégâts complets']],s.saveEffect||'half')}${field('Dés de dégâts','spl-dice',s.damageDice)}${selectField('Mod. dégâts','spl-dmgmode',[['none','Aucun'],['ability','Caractéristique'],['custom','Valeur personnalisée']],s.damageMod)}${field('Mod. dégâts personnalisé','spl-customdmg',s.customDamage,'number')}${field('Type de dégâts','spl-dmgtype',s.damageType)}${field('Ajustement attaque','spl-atkadj',s.attackAdjustment,'number')}${field('Ajustement DD','spl-dcadj',s.dcAdjustment,'number')}</div><label>Description<textarea id="spl-desc">${esc(s.description||'')}</textarea></label><div class="sheet-actions">${id==='new'?'':btn('Supprimer',`delete-spell|${s.id}`,'danger')}<button id="save-spell" class="primary">Enregistrer</button></div>`);$('#save-spell').onclick=()=>{const n={...s,name:$('#spl-name').value.trim()||'Sort',level:clamp(Number($('#spl-level').value||0),0,9),school:$('#spl-school').value,mode:$('#spl-mode').value,ability:$('#spl-ability').value,saveAttr:$('#spl-save').value,saveEffect:$('#spl-saveeffect').value,damageDice:$('#spl-dice').value.trim(),damageMod:$('#spl-dmgmode').value,customDamage:Number($('#spl-customdmg').value||0),damageType:$('#spl-dmgtype').value,attackAdjustment:Number($('#spl-atkadj').value||0),dcAdjustment:Number($('#spl-dcadj').value||0),description:$('#spl-desc').value};mutate(st=>{const i=st.spells.findIndex(x=>x.id===n.id);if(i<0)st.spells.push(n);else st.spells[i]=n});close()}}
function featureDetail(classId,name,index){const fs=allFeatures(),f=fs[Number(index)]||fs.find(x=>x.classId===classId&&x.name===name);if(!f)return;const isSub=f.kind==='subclass';show(f.name,`<div class="detail-hero">${icon(isSub?'Interface/etoile':f.classId==='custom'?'Interface/crayon':'Interface/eclair')}<div><b>${esc(f.className)} · niveau ${f.level}</b><small style="display:block">${esc(f.action||'Passif')}${f.source?` · ${esc(f.source)}`:''}</small></div></div><div class="detail-copy">${esc(f.detail||f.summary)}</div>${isSub?`<div class="callout">Aptitude de sous-classe Legacy · ${esc(f.source||'source officielle')}. Les calculs déterministes pris en charge par le compagnon sont appliqués automatiquement ; les choix contextuels restent à sélectionner en jeu.</div>`:''}${f.resource?`<div class="callout">Ressource associée : ${esc(resourceBlueprints(state.character).find(r=>r.id===f.resource||r.id.endsWith('_'+f.resource))?.name||f.resource)}</div>`:''}${f.classId==='custom'?btn('Modifier cette aptitude',`edit-feature|${f.id}`,'quiet'):''}`,'APTITUDE')}
function featureEditor(id){const f=id==='new'?{id:uid(),name:'Nouvelle aptitude',level:1,summary:'',detail:'',action:'Passif'}:state.customFeatures.find(x=>x.id===id);if(!f)return;show('Aptitude personnalisée',`${field('Nom','fea-name',f.name)}${field('Niveau indicatif','fea-level',f.level,'number','min="1" max="20"')}${field('Usage / action','fea-action',f.action)}${field('Résumé','fea-summary',f.summary)}<label>Détails<textarea id="fea-detail">${esc(f.detail)}</textarea></label><div class="sheet-actions">${id==='new'?'':btn('Supprimer',`delete-feature|${f.id}`,'danger')}<button id="save-feature" class="primary">Enregistrer</button></div>`);$('#save-feature').onclick=()=>{const n={...f,name:$('#fea-name').value.trim()||'Aptitude',level:Number($('#fea-level').value||1),action:$('#fea-action').value,summary:$('#fea-summary').value,detail:$('#fea-detail').value};mutate(s=>{const i=s.customFeatures.findIndex(x=>x.id===n.id);if(i<0)s.customFeatures.push(n);else s.customFeatures[i]=n});close()}}
function resourceEditor(id){const r=id==='new'?{id:uid(),name:'Nouvelle ressource',max:1,current:1,recharge:'Repos long'}:state.customResources.find(x=>x.id===id);if(!r)return;show('Ressource personnalisée',`${field('Nom','res-name',r.name)}<div class="grid2">${field('Maximum','res-max',r.max,'number','min="0"')}${field('Actuel','res-current',r.current,'number','min="0"')}${field('Recharge','res-recharge',r.recharge)}</div><div class="sheet-actions">${id==='new'?'':btn('Supprimer',`delete-resource|${r.id}`,'danger')}<button id="save-resource" class="primary">Enregistrer</button></div>`);$('#save-resource').onclick=()=>{const max=Math.max(0,Number($('#res-max').value||0)),n={...r,name:$('#res-name').value.trim()||'Ressource',max,current:clamp(Number($('#res-current').value||0),0,max),recharge:$('#res-recharge').value};mutate(s=>{const i=s.customResources.findIndex(x=>x.id===n.id);if(i<0)s.customResources.push(n);else s.customResources[i]=n});close()}}
function itemEditor(id){const i=id==='new'?{id:uid(),name:'Nouvel objet',type:'Équipement',quantity:1,description:'',equipped:false,magic:false,icon:'Inventaire/divers'}:state.items.find(x=>x.id===id);if(!i)return;show('Objet',`${field('Nom','item-name',i.name)}<div class="grid2">${field('Type','item-type',i.type)}${field('Quantité','item-qty',i.quantity,'number','min="0"')}</div>${selectField('Icône','item-icon',ITEM_ICONS,i.icon||'Inventaire/divers')}${check('Équipé','item-equipped',i.equipped)}${check('Objet magique','item-magic',i.magic)}<label>Description<textarea id="item-desc">${esc(i.description)}</textarea></label><div class="sheet-actions">${id==='new'?'':btn('Supprimer',`delete-item|${i.id}`,'danger')}<button id="save-item" class="primary">Enregistrer</button></div>`);$('#save-item').onclick=()=>{const n={...i,name:$('#item-name').value.trim()||'Objet',type:$('#item-type').value,quantity:Math.max(0,Number($('#item-qty').value||0)),icon:$('#item-icon').value,equipped:$('#item-equipped').checked,magic:$('#item-magic').checked,description:$('#item-desc').value};mutate(s=>{const x=s.items.findIndex(v=>v.id===n.id);if(x<0)s.items.push(n);else s.items[x]=n});close()}}
function itemDetail(id){const i=state.items.find(x=>x.id===id);if(!i)return;show(i.name,`<div class="detail-hero">${icon(i.icon||'Inventaire/divers')}<div><b>${esc(i.type)}</b><small style="display:block">Quantité ${i.quantity}${i.equipped?' · équipé':''}</small></div></div><div class="detail-copy">${esc(i.description||'Aucune description.')}</div>${btn('Modifier',`edit-item|${i.id}`,'quiet')}`)}
function coins(){show('Bourse',`<div class="grid2">${Object.keys(state.coins).map(k=>field(k.toUpperCase(),`coin-${k}`,state.coins[k],'number','min="0"')).join('')}</div><button id="save-coins" class="primary">Enregistrer</button>`);$('#save-coins').onclick=()=>{mutate(s=>{for(const k of Object.keys(s.coins))s.coins[k]=Math.max(0,Number($(`#coin-${k}`).value||0))});close()}}
function noteEditor(id){const n=id==='new'?{id:uid(),title:'',body:'',tags:'',category:'general',deleted:false,updatedAt:new Date().toISOString()}:state.notes.find(x=>x.id===id);if(!n)return;show('Note',`${field('Titre','note-title',n.title)}${selectField('Catégorie','note-cat',state.categories.map(c=>[c.id,c.name]),n.category)}<label>Texte<textarea id="note-body" class="note-editor">${esc(n.body)}</textarea></label>${field('Tags','note-tags',n.tags)}<div class="sheet-actions">${id==='new'?'':btn(n.deleted?'Restaurer':'Corbeille',`toggle-note|${n.id}`,'quiet')}<button id="save-note" class="primary">Enregistrer</button></div>`);$('#save-note').onclick=()=>{const x={...n,title:$('#note-title').value,category:$('#note-cat').value,body:$('#note-body').value,tags:$('#note-tags').value,updatedAt:new Date().toISOString()};mutate(s=>{const i=s.notes.findIndex(v=>v.id===x.id);if(i<0)s.notes.push(x);else s.notes[i]=x});close()}}
function conditions(){const common=['À terre','Agrippé','Aveuglé','Charmé','Effrayé','Empoisonné','Entravé','Étourdi','Inconscient','Invisible','Neutralisé','Paralysé','Pétrifié','Sourd'];show('États',`<div class="state-list">${common.map(c=>btn(c,`toggle-condition|${encodeURIComponent(c)}`,state.conditions.includes(c)?'on':'')).join('')}</div>`)}
function freeDice(){show('Dés libres',`${field('Expression','dice-expr','1d20')}<button id="free-roll" class="primary">Lancer</button><div id="free-output"></div>`);$('#free-roll').onclick=()=>{const r=parseDice($('#dice-expr').value);$('#free-output').innerHTML=`<div class="roll-result"><div class="total">${r.total}</div><p>${esc(r.label)} · ${r.rolls.join(', ')}</p></div>`}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${state.character.name.replace(/\W+/g,'_')||'personnage'}-compagnon.json`;a.click();URL.revokeObjectURL(a.href)}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const raw=JSON.parse(await input.files[0].text());state=normalize(raw);syncResources();persist();close();render();toast('Sauvegarde importée.')}catch{toast('Fichier incompatible.')}};input.click()}

function handle(cmd){const [a,b,c,dv]=cmd.split('|');switch(a){case'nav':view=b;render();break;case'combat-tab':combatTab=b;render();break;case'social-tab':socialTab=b;render();break;case'settings':settings();break;case'character':characterEditor();break;case'health':health();break;case'resources':resources();break;case'slots':slotsEditor();break;case'rest':rest();break;case'skills-editor':skillsEditor();break;case'custom-features':customFeatures();break;case'attack':attackRoll(b);break;case'spell':spellRoll(b);break;case'feature':featureDetail(decodeURIComponent(b),decodeURIComponent(c),dv);break;case'edit-attack':attackEditor(b);break;case'edit-spell':spellEditor(b);break;case'edit-feature':featureEditor(b);break;case'edit-resource':resourceEditor(b);break;case'edit-item':itemEditor(b);break;case'item':itemDetail(b);break;case'coins':coins();break;case'edit-note':noteEditor(b);break;case'conditions':conditions();break;case'free-dice':freeDice();break;case'roll':{if(b==='initiative')rollModal('Initiative',d().initiative,{defaultMode:classLevel(state.character,'barbarian')>=7?'adv':'normal'});else if(b==='save')rollModal(`Sauvegarde · ${ATTRS[c]}`,saveBonus(c));else if(b==='skill'){const prof=state.character.skills[c]?.proficiency||0;rollModal(SKILLS.find(x=>x[0]===c)?.[1]||'Compétence',skillBonus(c),{minNatural:classLevel(state.character,'rogue')>=11&&prof>0?10:1});}else if(b==='check')rollModal(`Test · ${ATTRS[c]}`,checkBonus(c));break}case'start-turn':mutate(s=>{s.turn.phase='active';s.turn.action=s.turn.bonus=s.turn.reaction=false;s.turn.attacksLeft=0});break;case'end-turn':mutate(s=>{s.turn.phase='waiting';s.turn.number++});break;case'cancel-turn':mutate(s=>{s.turn.action=s.turn.bonus=s.turn.reaction=false;s.turn.attacksLeft=0});break;case'reset-encounter':mutate(s=>s.turn={number:1,phase:'waiting',action:false,bonus:false,reaction:false,attacksLeft:0});break;case'resource-dec':mutate(s=>{if(b==='class')s.classResourceCurrent[c]=Math.max(0,s.classResourceCurrent[c]-1);else{const r=s.customResources.find(x=>x.id===c);if(r)r.current=Math.max(0,r.current-1)}});resources();break;case'resource-inc':mutate(s=>{if(b==='class'){const max=resourceBlueprints(s.character).find(x=>x.id===c)?.max||0;s.classResourceCurrent[c]=Math.min(max,s.classResourceCurrent[c]+1)}else{const r=s.customResources.find(x=>x.id===c);if(r)r.current=Math.min(r.max,r.current+1)}});resources();break;case'do-rest':{mutate(s=>{const blue=resourceBlueprints(s.character);if(b==='long'){s.hp=s.character.maxHp;s.tempHp=0;s.slotUsed=Array(9).fill(0);s.pactUsed=0;for(const r of blue)s.classResourceCurrent[r.id]=r.max;for(const r of s.customResources)if(/long/i.test(r.recharge))r.current=r.max}else{for(const r of blue)if(/court/i.test(r.recharge))s.classResourceCurrent[r.id]=r.max;s.pactUsed=0;for(const r of s.customResources)if(/court/i.test(r.recharge))r.current=r.max}});close();toast(`Repos ${b==='long'?'long':'court'} appliqué.`);break}case'delete-attack':mutate(s=>s.attacks=s.attacks.filter(x=>x.id!==b));close();break;case'delete-spell':mutate(s=>s.spells=s.spells.filter(x=>x.id!==b));close();break;case'delete-feature':mutate(s=>s.customFeatures=s.customFeatures.filter(x=>x.id!==b));close();break;case'delete-resource':mutate(s=>s.customResources=s.customResources.filter(x=>x.id!==b));close();break;case'delete-item':mutate(s=>s.items=s.items.filter(x=>x.id!==b));close();break;case'toggle-condition':{const name=decodeURIComponent(b);mutate(s=>s.conditions=s.conditions.includes(name)?s.conditions.filter(x=>x!==name):[...s.conditions,name]);conditions();break}case'toggle-note':mutate(s=>{const n=s.notes.find(x=>x.id===b);if(n)n.deleted=!n.deleted});close();break;case'trash':trash=!trash;render();break;case'export':exportData();break;case'import':importData();break;case'hard-reset':if(confirm('Réinitialiser complètement ce compagnon ?')){state=fresh();syncResources();persist();close();render()}break}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-cmd]');if(el&&!el.disabled){e.preventDefault();handle(el.dataset.cmd)}});

if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
